// fir Optimizer — P3.6 Linear Scan Register Allocator
//
// 알고리즘: Poletto & Sarkar (1999) Linear Scan
//
//   1. RPO 순서로 instruction에 index 부여
//   2. 각 SSA 값의 live interval [first_def, last_use] 계산
//   3. interval을 start 기준 정렬
//   4. active 집합 관리 (end 기준)
//      - 가용 레지스터 있으면 할당
//      - 없으면 spill (active 중 end가 가장 큰 interval)
//   5. 반환: RegAllocResult (name → phys reg index 또는 -1=spill)
//
// 가용 레지스터 (x86-64):
//   예약(임시): RAX(0), RCX(1), RDX(2)
//   인자/반환:  RDI(7), RSI(6), R8(8), R9(9)
//   RegAlloc:  RBX(3), R10(10), R11(11), R12(12), R13(13), R14(14), R15(15)
package opt

import (
	"fir/src/ir"
	"sort"
)

// ----------------------------------------------------------------
// 물리 레지스터 인덱스 (x86-64)
// ----------------------------------------------------------------

// RegAllocRegs: linear scan이 할당할 수 있는 물리 레지스터 인덱스 목록
// codegen.Reg 타입(byte)과 동일한 인코딩
var RegAllocRegs = []int{3, 10, 11, 12, 13, 14, 15} // RBX, R10..R15

// ----------------------------------------------------------------
// LiveInterval
// ----------------------------------------------------------------

type LiveInterval struct {
	Name  string
	Start int // 정의 위치 (instruction index)
	End   int // 마지막 사용 위치
}

// ----------------------------------------------------------------
// RegAllocResult
// ----------------------------------------------------------------

type RegAllocResult struct {
	// PhysReg[name] = RegAllocRegs 인덱스 (0..6)
	// -1 이면 spill (스택 슬롯 사용)
	PhysReg map[string]int
}

func NewRegAllocResult() *RegAllocResult {
	return &RegAllocResult{PhysReg: map[string]int{}}
}

// ----------------------------------------------------------------
// 함수 단위 RegAlloc 진입점
// ----------------------------------------------------------------

func RegAllocFunc(fn *ir.Function) *RegAllocResult {
	// 1. instruction index 부여 (RPO 순)
	rpo := reversePostOrder(fn)
	blockMap := makeBlockMap(fn)

	instIdx := map[*ir.Inst]int{}
	idx := 0
	for _, label := range rpo {
		b, ok := blockMap[label]
		if !ok {
			continue
		}
		for _, inst := range b.Insts {
			instIdx[inst] = idx
			idx++
		}
	}
	total := idx

	// 2. live interval 계산
	intervals := computeIntervals(fn, rpo, blockMap, instIdx, total)

	// 3. linear scan
	return linearScan(intervals)
}

// ----------------------------------------------------------------
// Live Interval 계산
// ----------------------------------------------------------------

func computeIntervals(fn *ir.Function, rpo []string,
	blockMap map[string]*ir.Block, instIdx map[*ir.Inst]int, total int,
) []LiveInterval {

	def := map[string]int{}  // name → 정의 index
	use := map[string]int{}  // name → 마지막 사용 index

	updateUse := func(name string, i int) {
		if cur, ok := use[name]; !ok || i > cur {
			use[name] = i
		}
	}

	for _, label := range rpo {
		b, ok := blockMap[label]
		if !ok {
			continue
		}
		for _, inst := range b.Insts {
			i := instIdx[inst]

			// 정의
			if inst.Result != "" {
				if _, ok := def[inst.Result]; !ok {
					def[inst.Result] = i
				}
			}

			// 사용 (operand)
			for _, name := range usedRegs(inst) {
				updateUse(name, i)
			}
		}
	}

	// 파라미터: index -1에서 정의 (함수 진입 전)
	for _, p := range fn.Params {
		if _, ok := def[p.Name]; !ok {
			def[p.Name] = 0
		}
	}

	// 사용만 있고 정의가 없는 경우 (파라미터 등) 보정
	for name, u := range use {
		if _, ok := def[name]; !ok {
			def[name] = 0
			_ = u
		}
	}

	// interval 목록 생성
	var intervals []LiveInterval
	for name, d := range def {
		end := d // 사용이 없으면 정의 위치
		if u, ok := use[name]; ok && u > end {
			end = u
		}
		intervals = append(intervals, LiveInterval{Name: name, Start: d, End: end})
	}

	return intervals
}

// ----------------------------------------------------------------
// Linear Scan
// ----------------------------------------------------------------

func linearScan(intervals []LiveInterval) *RegAllocResult {
	result := NewRegAllocResult()

	// start 기준 정렬
	sort.Slice(intervals, func(i, j int) bool {
		return intervals[i].Start < intervals[j].Start
	})

	// 가용 레지스터 풀
	freeRegs := make([]bool, len(RegAllocRegs))
	for i := range freeRegs {
		freeRegs[i] = true
	}

	// active: 현재 레지스터를 점유 중인 interval 목록
	// end 기준 정렬 유지
	type activeEntry struct {
		iv  LiveInterval
		reg int // RegAllocRegs 인덱스
	}
	var active []activeEntry

	expireActive := func(cur LiveInterval) {
		// end < cur.Start 인 active 제거 (레지스터 반환)
		var kept []activeEntry
		for _, ae := range active {
			if ae.iv.End < cur.Start {
				freeRegs[ae.reg] = true // 반환
			} else {
				kept = append(kept, ae)
			}
		}
		active = kept
	}

	pickFree := func() int {
		for i, free := range freeRegs {
			if free {
				return i
			}
		}
		return -1
	}

	// active에서 End가 가장 큰 entry 반환 (spill 대상)
	spillCandidate := func() int {
		maxEnd := -1
		maxIdx := -1
		for i, ae := range active {
			if ae.iv.End > maxEnd {
				maxEnd = ae.iv.End
				maxIdx = i
			}
		}
		return maxIdx
	}

	for _, iv := range intervals {
		expireActive(iv)

		reg := pickFree()
		if reg >= 0 {
			// 레지스터 할당
			freeRegs[reg] = false
			result.PhysReg[iv.Name] = reg

			// active에 삽입 (end 기준 정렬)
			ae := activeEntry{iv: iv, reg: reg}
			inserted := false
			for i, a := range active {
				if iv.End < a.iv.End {
					active = append(active[:i], append([]activeEntry{ae}, active[i:]...)...)
					inserted = true
					break
				}
			}
			if !inserted {
				active = append(active, ae)
			}
		} else {
			// spill: active 중 가장 늦게 끝나는 것과 비교
			ci := spillCandidate()
			if ci >= 0 && active[ci].iv.End > iv.End {
				// 기존 active를 spill하고 iv에 레지스터 양보
				spilledName := active[ci].iv.Name
				reg = active[ci].reg
				result.PhysReg[spilledName] = -1 // spill

				result.PhysReg[iv.Name] = reg
				active[ci] = activeEntry{iv: iv, reg: reg}

				// active 재정렬 (end 기준)
				sort.Slice(active, func(i, j int) bool {
					return active[i].iv.End < active[j].iv.End
				})
			} else {
				// iv 자체를 spill
				result.PhysReg[iv.Name] = -1
			}
		}
	}

	return result
}

// fir Phase 3.6 — RegAlloc 검증
// 원칙: interp(optimized) == native(regalloc) 결과 동일
//
// 주의: ELF _start는 인자 없이 f()를 호출한다.
//       따라서 native 검증은 인자 없는 함수 (상수 반환)로 작성하거나
//       irgen 함수 내에 리터럴 값을 박아서 사용한다.
package main

import (
	"fmt"
	"fir/src/codegen"
	"fir/src/interp"
	"fir/src/irgen"
	"fir/src/opt"
)

var raPassed, raFailed int

// ----------------------------------------------------------------
// 헬퍼: interp(opt) == native(RA) 검증
// src는 인자 없는 함수여야 함 (ELF 실행 제약)
// ----------------------------------------------------------------

func assertRegAlloc(label, src, fnName string, expected int64) {
	mod, err := irgen.Compile(src)
	if err != nil {
		fmt.Printf("[FAIL] %s | irgen: %v\n", label, err)
		raFailed++
		return
	}

	// interp (최적화 전)
	interpBefore, err := interp.ExecModule(mod, fnName, nil)
	if err != nil {
		fmt.Printf("[FAIL] %s | interp: %v\n", label, err)
		raFailed++
		return
	}
	if interpBefore.AsInt() != expected {
		fmt.Printf("[FAIL] %s | interp=%d expected=%d\n", label, interpBefore.AsInt(), expected)
		raFailed++
		return
	}

	// opt.Full() 적용
	modOpt := opt.Full().Run(mod)

	// interp (최적화 후) — 의미 보존 확인
	interpAfter, err := interp.ExecModule(modOpt, fnName, nil)
	if err != nil {
		fmt.Printf("[FAIL] %s | interp(opt): %v\n", label, err)
		raFailed++
		return
	}
	if interpAfter.AsInt() != expected {
		fmt.Printf("[FAIL] %s | interp(opt)=%d expected=%d (opt broke semantics!)\n",
			label, interpAfter.AsInt(), expected)
		raFailed++
		return
	}

	// RegAlloc: 함수별 계산
	raMap := make(map[string]*opt.RegAllocResult)
	for _, fn := range modOpt.Functions {
		raMap[fn.Name] = opt.RegAllocFunc(fn)
	}

	// RegAlloc 통계
	ra := raMap[fnName]
	physCount, spillCount := 0, 0
	if ra != nil {
		for _, idx := range ra.PhysReg {
			if idx >= 0 {
				physCount++
			} else {
				spillCount++
			}
		}
	}

	// native 실행 (RegAlloc 적용 코드젠)
	cm, err := codegen.CompileModuleWithRA(modOpt, raMap)
	if err != nil {
		fmt.Printf("[FAIL] %s | codegen(ra): %v\n", label, err)
		raFailed++
		return
	}

	off, ok := cm.FuncOff[fnName]
	if !ok {
		fmt.Printf("[FAIL] %s | entry not found\n", label)
		raFailed++
		return
	}

	elfBytes := codegen.BuildELFWithEntry(cm.Code, off)
	exitCode, err := execElf(elfBytes)
	if err != nil {
		fmt.Printf("[SKIP] %s | native: %v\n", label, err)
		return
	}

	// exit code는 unsigned byte (0-255)
	expectedExit := expected & 0xFF
	if exitCode == expectedExit {
		fmt.Printf("[PASS] %s | result=%d regs=%d spills=%d\n",
			label, exitCode, physCount, spillCount)
		raPassed++
	} else {
		fmt.Printf("[FAIL] %s | native=%d expected=%d (interp=%d)\n",
			label, exitCode, expectedExit, interpAfter.AsInt())
		raFailed++
	}
}

// ----------------------------------------------------------------
// 테스트: 모두 인자 없는 함수 (ELF _start 제약)
// ----------------------------------------------------------------

func testRegAlloc() {
	fmt.Println("--- P3.6: Linear Scan Register Allocation ---")

	// RA-1: 상수 반환 (가장 단순)
	assertRegAlloc("RA-1: const 42",
		`fn f() -> i64 { return 42 }`,
		"f", 42)

	// RA-2: 단순 연산 (상수 폴딩 후 레지스터 할당)
	assertRegAlloc("RA-2: const expr 3*4+2=14",
		`fn f() -> i64 {
			let x: i64 = 3 * 4
			let y: i64 = x + 2
			return y
		}`,
		"f", 14)

	// RA-3: if/else 분기 (phi 후 레지스터)
	// 10 > 5 → true → return 1
	assertRegAlloc("RA-3: if/else → 1",
		`fn f() -> i64 {
			let x: i64 = 10
			let r: i64 = 0
			if x > 5 {
				r = 1
			} else {
				r = 2
			}
			return r
		}`,
		"f", 1)

	// RA-3b: if/else false 경로
	// 3 > 5 → false → return 2
	assertRegAlloc("RA-3b: if/else → 2",
		`fn f() -> i64 {
			let x: i64 = 3
			let r: i64 = 0
			if x > 5 {
				r = 1
			} else {
				r = 2
			}
			return r
		}`,
		"f", 2)

	// RA-4: while 루프 (루프 변수 레지스터 유지)
	// sum(0..4) = 0+1+2+3+4 = 10
	assertRegAlloc("RA-4: while sum=10",
		`fn f() -> i64 {
			let s: i64 = 0
			let i: i64 = 0
			while i < 5 {
				s = s + i
				i = i + 1
			}
			return s
		}`,
		"f", 10)

	// RA-5: 다변수 (여러 SSA 값 동시 레지스터)
	assertRegAlloc("RA-5: multi var 3*4+5*6=42",
		`fn f() -> i64 {
			let a: i64 = 3 * 4
			let b: i64 = 5 * 6
			let c: i64 = a + b
			return c
		}`,
		"f", 42)

	// RA-6: 중첩 연산 (레지스터 압박)
	assertRegAlloc("RA-6: nested ops",
		`fn f() -> i64 {
			let a: i64 = 2
			let b: i64 = a + 3
			let c: i64 = b * 4
			let d: i64 = c - 1
			let e: i64 = d + 2
			return e
		}`,
		"f", 21)

	// RA-7: 재귀 함수 (factorial(5)=120)
	assertRegAlloc("RA-7: factorial(5)=120",
		`fn factorial(n: i64) -> i64 {
			if n <= 1 { return 1 }
			return n * factorial(n - 1)
		}
		fn f() -> i64 {
			return factorial(5)
		}`,
		"f", 120)
}

func runRATests() {
	fmt.Println()
	fmt.Println("=== RegAlloc Tests (Phase 3.6) ===")

	testRegAlloc()

	fmt.Println()
	fmt.Printf("RegAlloc Results: %d/%d PASS\n", raPassed, raPassed+raFailed)
	if raFailed == 0 {
		fmt.Println()
		fmt.Println("REGALLOC VERIFIED")
		fmt.Println("interp == native (with register allocation)")
	}
}

// fir Codegen — RegAlloc 통합 코드젠
//
// RegAllocResult를 받아 SSA 값을 물리 레지스터에서 직접 읽고 씀
// 레지스터 할당 실패(spill)된 값은 기존 스택 슬롯 경로를 그대로 사용
package codegen

import (
	"fmt"
	"fir/src/ir"
	"fir/src/opt"
	"math"
)

// ----------------------------------------------------------------
// 물리 레지스터 매핑
// opt.RegAllocRegs 인덱스 → codegen.Reg
// ----------------------------------------------------------------

var raPhysRegs = []Reg{
	RBX, R10, R11, R12, R13, R14, R15,
}

// ----------------------------------------------------------------
// FuncCompilerRA: RegAlloc 결과를 활용하는 함수 컴파일러
// ----------------------------------------------------------------

type FuncCompilerRA struct {
	fn      *ir.Function
	asm     *Asm
	ra      *opt.RegAllocResult // nil이면 기존 스택 전용
	slots   map[string]int32    // spill 슬롯 (rbp 기준 음수 offset)
	nextOff int32
	funcMap map[string]string
}

func newFuncCompilerRA(fn *ir.Function, a *Asm,
	ra *opt.RegAllocResult, funcMap map[string]string,
) *FuncCompilerRA {
	return &FuncCompilerRA{
		fn:      fn,
		asm:     a,
		ra:      ra,
		slots:   make(map[string]int32),
		nextOff: 0,
		funcMap: funcMap,
	}
}

// physReg: SSA 이름 → 물리 Reg. 없으면 (0, false).
func (fc *FuncCompilerRA) physReg(name string) (Reg, bool) {
	if fc.ra == nil {
		return 0, false
	}
	idx, ok := fc.ra.PhysReg[name]
	if !ok || idx < 0 || idx >= len(raPhysRegs) {
		return 0, false
	}
	return raPhysRegs[idx], true
}

// slot: spill된 값의 스택 슬롯 (기존 FuncCompiler.slot 과 동일)
func (fc *FuncCompilerRA) slot(name string) int32 {
	return fc.slotN(name, 8)
}

func (fc *FuncCompilerRA) slotN(name string, n int32) int32 {
	if off, ok := fc.slots[name]; ok {
		return off
	}
	if n < 8 {
		n = 8
	}
	aligned := (n + 7) &^ 7
	fc.nextOff -= aligned
	fc.slots[name] = fc.nextOff
	return fc.nextOff
}

func (fc *FuncCompilerRA) stackSize() int32 {
	size := -fc.nextOff
	if size <= 0 {
		size = 1
	}
	aligned := ((size + 15) / 16) * 16
	size = aligned - 8
	if size <= 0 {
		size = 8
	}
	return size
}

// loadVal: v를 dst 레지스터에 로드
func (fc *FuncCompilerRA) loadVal(dst Reg, v *ir.Value) {
	if v == nil {
		fc.asm.MovRI32(dst, 0)
		return
	}
	switch v.Kind {
	case ir.ValConstInt:
		fc.asm.MovRI(dst, v.IVal)
	case ir.ValConstFloat:
		bits := int64(math.Float64bits(v.FVal))
		fc.asm.MovRI(dst, bits)
	case ir.ValConstBool:
		if v.BVal {
			fc.asm.MovRI32(dst, 1)
		} else {
			fc.asm.MovRI32(dst, 0)
		}
	case ir.ValConstNull:
		fc.asm.MovRI32(dst, 0)
	case ir.ValReg:
		if pr, ok := fc.physReg(v.Name); ok {
			// 레지스터 → 레지스터
			if pr != dst {
				fc.asm.MovRR(dst, pr)
			}
		} else {
			// 스택 → 레지스터
			fc.asm.LoadStack(dst, fc.slot(v.Name))
		}
	case ir.ValGlobalRef:
		fc.asm.MovRI32(dst, 0)
	}
}

// storeResult: src 레지스터의 값을 SSA 이름에 저장
func (fc *FuncCompilerRA) storeResult(name string, src Reg) {
	if pr, ok := fc.physReg(name); ok {
		if pr != src {
			fc.asm.MovRR(pr, src)
		}
	} else {
		fc.asm.StoreStack(fc.slot(name), src)
	}
}

// ----------------------------------------------------------------
// Instruction 컴파일
// ----------------------------------------------------------------

func (fc *FuncCompilerRA) compileInst(inst *ir.Inst) error {
	a := fc.asm
	switch inst.Kind {

	case ir.InstBinop:
		fc.loadVal(RAX, inst.LHS) // RAX = lhs
		a.StoreStack(fc.slot("__tmp_lhs__"), RAX)
		fc.loadVal(RAX, inst.RHS) // RAX = rhs
		a.MovRR(RCX, RAX)
		a.LoadStack(RAX, fc.slot("__tmp_lhs__"))

		switch inst.Op {
		case "add":
			a.AddRR(RAX, RCX)
		case "sub":
			a.SubRR(RAX, RCX)
		case "mul":
			a.IMulRR(RAX, RCX)
		case "div":
			a.CQO()
			a.IDiv(RCX)
		case "rem":
			a.CQO()
			a.IDiv(RCX)
			a.MovRR(RAX, RDX)
		case "and":
			a.emit(rex(true, RCX, RAX), 0x21, modrm(0b11, RCX, RAX))
		case "or":
			a.emit(rex(true, RCX, RAX), 0x09, modrm(0b11, RCX, RAX))
		case "xor":
			a.emit(rex(true, RCX, RAX), 0x31, modrm(0b11, RCX, RAX))
		case "shl":
			a.ShlRC()
		case "shr":
			a.ShrRC()
		case "fadd":
			a.MovqXmm0RAX(); a.MovqXmm1RCX(); a.AddsdXmm(); a.MovqRAXXmm0()
		case "fsub":
			a.MovqXmm0RAX(); a.MovqXmm1RCX(); a.SubsdXmm(); a.MovqRAXXmm0()
		case "fmul":
			a.MovqXmm0RAX(); a.MovqXmm1RCX(); a.MulsdXmm(); a.MovqRAXXmm0()
		case "fdiv":
			a.MovqXmm0RAX(); a.MovqXmm1RCX(); a.DivsdXmm(); a.MovqRAXXmm0()
		}
		fc.storeResult(inst.Result, RAX)

	case ir.InstNeg:
		fc.loadVal(RAX, inst.Operand)
		a.NegR(RAX)
		fc.storeResult(inst.Result, RAX)

	case ir.InstICmp:
		fc.loadVal(RAX, inst.LHS)
		a.StoreStack(fc.slot("__tmp_lhs__"), RAX)
		fc.loadVal(RAX, inst.RHS)
		a.MovRR(RCX, RAX)
		a.LoadStack(RAX, fc.slot("__tmp_lhs__"))
		a.CmpRR(RAX, RCX)
		var cc byte
		switch inst.Pred {
		case "eq":  cc = 0x94
		case "ne":  cc = 0x95
		case "lt":  cc = 0x9C
		case "le":  cc = 0x9E
		case "gt":  cc = 0x9F
		case "ge":  cc = 0x9D
		case "ult": cc = 0x92
		case "ule": cc = 0x96
		case "ugt": cc = 0x97
		case "uge": cc = 0x93
		default:    cc = 0x94
		}
		a.emit(0x0F, cc, 0xC0)
		a.MovzxAL()
		fc.storeResult(inst.Result, RAX)

	case ir.InstFCmp:
		fc.loadVal(RAX, inst.LHS)
		a.StoreStack(fc.slot("__tmp_lhs__"), RAX)
		fc.loadVal(RAX, inst.RHS)
		a.MovRR(RCX, RAX)
		a.LoadStack(RAX, fc.slot("__tmp_lhs__"))
		a.MovqXmm0RAX()
		a.MovqXmm1RCX()
		a.UcomisdXmm()
		var cc byte
		switch inst.Pred {
		case "oeq": cc = 0x94
		case "one": cc = 0x95
		case "olt": cc = 0x92
		case "ole": cc = 0x96
		case "ogt": cc = 0x97
		case "oge": cc = 0x93
		default:    cc = 0x94
		}
		a.emit(0x0F, cc, 0xC0)
		a.MovzxAL()
		fc.storeResult(inst.Result, RAX)

	case ir.InstCast:
		fc.loadVal(RAX, inst.Operand)
		switch inst.Op {
		case "sitofp":
			a.Cvtsi2sdXmm0RAX()
			a.MovqRAXXmm0()
		case "fptosi":
			a.MovqXmm0RAX()
			a.emit(0xF2, 0x48, 0x0F, 0x2C, 0xC0)
		case "trunc":
			switch inst.ToType.Name {
			case "i8",  "u8":  a.AndRI(RAX, 0xFF)
			case "i16", "u16": a.AndRI(RAX, 0xFFFF)
			case "i32", "u32": a.AndRI(RAX, int32(-1))
			}
		}
		fc.storeResult(inst.Result, RAX)

	case ir.InstAlloca:
		allocSize := int32(8)
		if inst.AllocType != nil && inst.AllocType.Size > 0 {
			allocSize = int32(inst.AllocType.Size)
		}
		off := fc.slotN(inst.Result+"__alloca__", allocSize)
		a.emit(rex(true, RAX, RBP), 0x8D, 0x85|byte(RAX&7)<<3)
		a.emit32(off)
		fc.storeResult(inst.Result, RAX)

	case ir.InstGEP:
		fc.loadVal(RAX, inst.Ptr)
		a.MovRR(RCX, RAX)
		stride := int64(1)
		if inst.ElemType != nil && inst.ElemType.Size > 0 {
			stride = int64(inst.ElemType.Size)
		}
		fc.loadVal(RAX, inst.Idx)
		if stride != 1 {
			a.MovRI(RDX, stride)
			a.IMulRR(RAX, RDX)
		}
		a.AddRR(RCX, RAX)
		a.MovRR(RAX, RCX)
		fc.storeResult(inst.Result, RAX)

	case ir.InstLoad:
		fc.loadVal(RAX, inst.Ptr)
		a.MovRR(RCX, RAX)
		a.emit(rex(true, RAX, RCX), 0x8B, modrm(0b00, RAX, RCX))
		fc.storeResult(inst.Result, RAX)

	case ir.InstStore:
		fc.loadVal(RAX, inst.Val)
		a.MovRR(RCX, RAX)
		fc.loadVal(RAX, inst.Ptr)
		a.MovRR(RDX, RAX)
		a.emit(rex(true, RCX, RDX), 0x89, modrm(0b00, RCX, RDX))

	case ir.InstCall:
		spillSlots := make([]int32, len(inst.Args))
		for i, arg := range inst.Args {
			if i >= len(argRegs) {
				break
			}
			fc.loadVal(RAX, arg)
			spillName := fmt.Sprintf("__call_spill_%d__", i)
			off := fc.slot(spillName)
			a.StoreStack(off, RAX)
			spillSlots[i] = off
		}
		for i := range inst.Args {
			if i >= len(argRegs) {
				break
			}
			a.LoadStack(argRegs[i], spillSlots[i])
		}
		calleeName := ""
		if inst.Callee != nil && inst.Callee.Kind == ir.ValGlobalRef {
			calleeName = inst.Callee.Name
		}
		label := calleeName + "__entry"
		if l, ok := fc.funcMap[calleeName]; ok {
			label = l
		}
		a.Call(label)
		if inst.Result != "" {
			fc.storeResult(inst.Result, RAX)
		}

	case ir.InstBr:
		a.Jmp(fc.fn.Name + "__" + inst.Target)

	case ir.InstBrCond:
		fc.loadVal(RAX, inst.Cond)
		a.CmpRI(RAX, 0)
		a.Jcc(JNE, fc.fn.Name+"__"+inst.TrueLabel)
		a.Jmp(fc.fn.Name + "__" + inst.FalseLabel)

	case ir.InstRet:
		fc.loadVal(RAX, inst.Val)
		fc.emitEpilogue()
		a.Ret()

	case ir.InstRetVoid:
		a.MovRI32(RAX, 0)
		fc.emitEpilogue()
		a.Ret()

	case ir.InstPhi:
		// phi: mem2reg+TrivialPhi 후 남은 phi는 스택 슬롯 경유
		// incoming 값을 이미 predecessor 블록에서 슬롯에 저장했다고 가정
		// (현재 codegen과 동일하게 phi 자체는 no-op — 슬롯에 값이 있음)
	}
	return nil
}

func (fc *FuncCompilerRA) emitEpilogue() {
	fc.asm.MovRR(RSP, RBP)
	fc.asm.Pop(RBP)
}

// ----------------------------------------------------------------
// 모듈 컴파일 (RegAlloc 사용)
// ----------------------------------------------------------------

// CompileModuleWithRA: opt.Full() + RegAlloc 결과를 받아 코드젠
// ra가 nil이면 기존 스택 전용 경로와 동일하게 동작
func CompileModuleWithRA(mod *ir.Module, raMap map[string]*opt.RegAllocResult) (*CompiledModule, error) {
	cm := &CompiledModule{
		FuncOff:  make(map[string]int),
		FuncSize: make(map[string]int),
	}

	sharedAsm := NewAsm()

	funcLabels := make(map[string]string)
	for _, fn := range mod.Functions {
		funcLabels[fn.Name] = fn.Name + "__entry"
	}

	for _, fn := range mod.Functions {
		off := sharedAsm.Len()
		cm.FuncOff[fn.Name] = off

		var ra *opt.RegAllocResult
		if raMap != nil {
			ra = raMap[fn.Name]
		}

		if err := compileFuncWithRA(sharedAsm, fn, ra, funcLabels); err != nil {
			return nil, fmt.Errorf("compile %s: %w", fn.Name, err)
		}

		cm.FuncSize[fn.Name] = sharedAsm.Len() - off
	}

	if err := sharedAsm.ResolveFixups(); err != nil {
		return nil, err
	}

	cm.Code = sharedAsm.Bytes()
	return cm, nil
}

func compileFuncWithRA(a *Asm, fn *ir.Function,
	ra *opt.RegAllocResult, funcLabels map[string]string,
) error {
	fc := newFuncCompilerRA(fn, a, ra, funcLabels)

	// 1패스: 슬롯 미리 할당 (spill된 값 + 임시 슬롯)
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Result != "" {
				if _, hasPhys := fc.physReg(inst.Result); !hasPhys {
					fc.slot(inst.Result)
				}
			}
		}
	}
	for _, p := range fn.Params {
		if _, hasPhys := fc.physReg(p.Name); !hasPhys {
			fc.slot(p.Name)
		}
	}
	fc.slot("__tmp_lhs__")

	frameSize := fc.stackSize()

	a.MarkLabel(fn.Name + "__entry")
	a.Push(RBP)
	a.MovRR(RBP, RSP)
	a.SubSP(frameSize)

	// 파라미터 → 물리 레지스터 또는 스택 슬롯
	for i, p := range fn.Params {
		if i >= len(argRegs) {
			break
		}
		if pr, ok := fc.physReg(p.Name); ok {
			a.MovRR(pr, argRegs[i])
		} else {
			a.StoreStack(fc.slot(p.Name), argRegs[i])
		}
	}

	// 블록 컴파일
	for _, b := range fn.Blocks {
		if b.Label != "entry" {
			a.MarkLabel(fn.Name + "__" + b.Label)
		}
		for _, inst := range b.Insts {
			if err := fc.compileInst(inst); err != nil {
				return err
			}
		}
	}

	return nil
}

