// fir Optimizer — P3.1 mem2reg (alloca → SSA phi)
//
// 알고리즘: Cytron et al. (1991) 표준 SSA 변환
//
//   1. promotable alloca 탐지  (load/store 전용, address-taken 아님)
//   2. CFG predecessors 구성
//   3. Dominance (idom) 계산  — Cooper et al. iterative
//   4. Dominance Frontier 계산
//   5. phi 삽입               — store 위치 → DF → phi node
//   6. rename                 — dominator tree DFS
//      alloca/store/load 제거, phi incoming 연결
package opt

import (
	"fmt"
	"fir/src/ir"
)

// ----------------------------------------------------------------
// Pass
// ----------------------------------------------------------------

type Mem2RegPass struct{}

func (p *Mem2RegPass) Name() string { return "mem2reg" }

func (p *Mem2RegPass) Run(mod *ir.Module) *ir.Module {
	for _, fn := range mod.Functions {
		if len(fn.Blocks) > 0 {
			mem2regFunc(fn)
		}
