// fir Optimizer — P3.5 Trivial Phi Elimination
//
// trivial phi: incoming이 1개인 phi → 해당 값으로 직접 치환
//
// 알고리즘:
//   1. 각 블록에서 incoming == 1인 phi 탐지
//   2. subst[phi.result] = incoming[0].Val 등록
//   3. 모듈 전체 instruction의 레지스터 참조를 subst로 치환
//   4. 치환된 phi instruction 제거
//   5. 변경이 없을 때까지 반복 (phi 체인 처리)
package opt

import "fir/src/ir"

// ----------------------------------------------------------------
// TrivialPhiPass
// ----------------------------------------------------------------

type TrivialPhiPass struct{}

func (p *TrivialPhiPass) Name() string { return "trivial-phi" }

func (p *TrivialPhiPass) Run(mod *ir.Module) *ir.Module {
	for _, fn := range mod.Functions {
		for trivialPhiElim(fn) {
		}
	}
	return mod
}

// ----------------------------------------------------------------
// 함수 단위 trivial phi 제거
// 반환값: 변경이 있었으면 true (호출자가 수렴까지 반복)
// ----------------------------------------------------------------

func trivialPhiElim(fn *ir.Function) bool {
	// 1. trivial phi 탐지: incoming == 1
	subst := map[string]*ir.Value{} // phi.result → 치환할 값
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Kind != ir.InstPhi {
				continue
			}
			if len(inst.Incoming) == 1 {
				subst[inst.Result] = inst.Incoming[0].Val
			}
		}
	}
	if len(subst) == 0 {
		return false
	}

	// resolve: subst 체인을 끝까지 따라감
	// (phi → phi → 실제 값 케이스 처리)
	resolve := func(v *ir.Value) *ir.Value {
		if v == nil || v.Kind != ir.ValReg {
			return v
		}
		cur := v
		for i := 0; i < 64; i++ {
			if cur == nil || cur.Kind != ir.ValReg {
				break
			}
			next, ok := subst[cur.Name]
			if !ok {
				break
			}
			cur = next
		}
		return cur
	}

	// 2. 모든 instruction의 레지스터 참조 치환
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			switch inst.Kind {
			case ir.InstBinop, ir.InstICmp, ir.InstFCmp:
				inst.LHS = resolve(inst.LHS)
				inst.RHS = resolve(inst.RHS)
			case ir.InstNeg, ir.InstCast:
				inst.Operand = resolve(inst.Operand)
			case ir.InstLoad:
				inst.Ptr = resolve(inst.Ptr)
			case ir.InstStore:
				inst.Val = resolve(inst.Val)
				inst.Ptr = resolve(inst.Ptr)
			case ir.InstGEP:
				inst.Ptr = resolve(inst.Ptr)
				inst.Idx = resolve(inst.Idx)
			case ir.InstCall:
				inst.Callee = resolve(inst.Callee)
				for i, a := range inst.Args {
					inst.Args[i] = resolve(a)
				}
			case ir.InstBrCond:
				inst.Cond = resolve(inst.Cond)
			case ir.InstRet:
				inst.Val = resolve(inst.Val)
			case ir.InstPhi:
				for i := range inst.Incoming {
					inst.Incoming[i].Val = resolve(inst.Incoming[i].Val)
				}
			}
		}
	}

	// 3. trivial phi instruction 제거
	for _, b := range fn.Blocks {
		kept := b.Insts[:0]
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstPhi && len(inst.Incoming) == 1 {
				continue // 제거
			}
			kept = append(kept, inst)
		}
		b.Insts = kept
	}

	return true
}

