import (
	"math"
	"fir/src/ir"
)

// ----------------------------------------------------------------
// ConstFoldPass
// ----------------------------------------------------------------

type ConstFoldPass struct{}

func (p *ConstFoldPass) Name() string { return "constfold" }

func (p *ConstFoldPass) Run(mod *ir.Module) *ir.Module {
	for _, fn := range mod.Functions {
		foldFunc(fn)
	}
	return mod
}

// ----------------------------------------------------------------
// 함수 단위 폴딩 (반복 수렴)
// ----------------------------------------------------------------

func foldFunc(fn *ir.Function) {
	// 수렴할 때까지 반복 (한 번에 다 안 될 수 있음)
	for {
		changed := false
		// env: %reg → 상수 Value (블록 경계 무시 — SSA 불변)
		env := map[string]*ir.Value{}
		for _, b := range fn.Blocks {
			if foldBlock(b, env) {
				changed = true
			}
		}
		if !changed {
			break
		}
	}
}

