// fir Optimizer — PassManager
// 모든 패스는 interp 결과를 보존해야 한다
package opt

import "fir/src/ir"

// ----------------------------------------------------------------
// Pass 인터페이스
// ----------------------------------------------------------------

type Pass interface {
	Name() string
	Run(mod *ir.Module) *ir.Module
}

// ----------------------------------------------------------------
// PassManager
// ----------------------------------------------------------------

type PassManager struct {
	passes []Pass
}

func NewPassManager() *PassManager {
	return &PassManager{}
}

func (pm *PassManager) Add(p Pass) {
	pm.passes = append(pm.passes, p)
}

func (pm *PassManager) Run(mod *ir.Module) *ir.Module {
	for _, p := range pm.passes {
		mod = p.Run(mod)
	}
	return mod
}

// Standard: ConstFold → DeadBlock → DCE
func Standard() *PassManager {
	pm := NewPassManager()
	pm.Add(&ConstFoldPass{})
	pm.Add(&DeadBlockPass{})
	pm.Add(&DCEPass{})
	return pm
}

// Full: ConstFold → DeadBlock → DCE → Mem2Reg → TrivialPhi → DCE
func Full() *PassManager {
	pm := NewPassManager()
	pm.Add(&ConstFoldPass{})
	pm.Add(&DeadBlockPass{})
	pm.Add(&DCEPass{})
	pm.Add(&Mem2RegPass{})
	pm.Add(&TrivialPhiPass{})
	pm.Add(&DCEPass{})
	return pm
}

