     1→// fir Optimizer — P3.2 Dead Code Elimination
     2→// 결과가 사용되지 않는 instruction 제거
     3→//
     4→// 알고리즘:
     5→//   1. alive 집합: ret/br/store/call = 항상 alive
     6→//   2. alive instruction의 모든 operand reg → alive에 추가
     7→//   3. 역방향 전파 (수렴까지 반복)
     8→//   4. alive 아닌 instruction 제거
     9→package opt
    10→
    11→import "fir/src/ir"
    12→
    13→// ----------------------------------------------------------------
    14→// DCEPass
    15→// ----------------------------------------------------------------
    16→
    17→type DCEPass struct{}
    18→
    19→func (p *DCEPass) Name() string { return "dce" }
    20→
    21→func (p *DCEPass) Run(mod *ir.Module) *ir.Module {
    22→	for _, fn := range mod.Functions {
    23→		dceFunc(fn)
    24→	}
    25→	return mod
    26→}
    27→
    28→// ----------------------------------------------------------------
    29→// 함수 단위 DCE
    30→// ----------------------------------------------------------------
    31→
    32→func dceFunc(fn *ir.Function) {
    33→	// 전체 instruction 수집
    34→	allInsts := []*ir.Inst{}
    35→	for _, b := range fn.Blocks {
    36→		allInsts = append(allInsts, b.Insts...)
    37→	}
    38→
    39→	// alive 집합: result 이름 → true
    40→	alive := make(map[string]bool)
    41→
    42→	// 1. 초기 alive: 사이드 이펙트 있는 instruction
    43→	for _, inst := range allInsts {
    44→		if isSideEffect(inst) {
    45→			markAlive(alive, inst)
    46→		}
    47→	}
    48→
    49→	// 2. use-def 체인으로 역방향 전파
    50→	// result → inst 맵
    51→	defMap := make(map[string]*ir.Inst)
    52→	for _, inst := range allInsts {
    53→		if inst.Result != "" {
    54→			defMap[inst.Result] = inst
    55→		}
    56→	}
    57→
    58→	// alive인 instruction의 operand를 alive로 마킹 (수렴까지)
    59→	for {
    60→		changed := false
    61→		for _, inst := range allInsts {
    62→			if !isInstAlive(alive, inst) { continue }
    63→			for _, used := range usedRegs(inst) {
    64→				if !alive[used] {
    65→					alive[used] = true
    66→					changed = true
    67→					// used를 정의하는 instruction도 alive
    68→					if def, ok := defMap[used]; ok {
    69→						markAlive(alive, def)
    70→					}
    71→				}
    72→			}
    73→		}
    74→		if !changed { break }
    75→	}
    76→
    77→	// 3. 제거
    78→	for _, b := range fn.Blocks {
    79→		kept := b.Insts[:0]
    80→		for _, inst := range b.Insts {
    81→			if isSideEffect(inst) || isInstAlive(alive, inst) {
    82→				kept = append(kept, inst)
    83→			}
    84→		}
    85→		b.Insts = kept
    86→	}
    87→}
    88→
    89→// ----------------------------------------------------------------
    90→// 헬퍼
    91→// ----------------------------------------------------------------
    92→
    93→// 사이드 이펙트: 항상 alive
    94→func isSideEffect(inst *ir.Inst) bool {
    95→	switch inst.Kind {
    96→	case ir.InstRet, ir.InstRetVoid,
    97→		ir.InstBr, ir.InstBrCond,
    98→		ir.InstStore, ir.InstCall:
    99→		return true
   100→	}
   101→	return false
   102→}
   103→
   104→// instruction이 alive 집합에 포함되는가
   105→func isInstAlive(alive map[string]bool, inst *ir.Inst) bool {
   106→	if inst.Result == "" { return isSideEffect(inst) }
   107→	return alive[inst.Result]
   108→}
   109→
   110→func markAlive(alive map[string]bool, inst *ir.Inst) {
   111→	if inst.Result != "" {
   112→		alive[inst.Result] = true
   113→	}
   114→}
   115→
   116→// instruction이 사용하는 레지스터 이름 목록
   117→func usedRegs(inst *ir.Inst) []string {
   118→	var regs []string
   119→	add := func(v *ir.Value) {
   120→		if v != nil && v.Kind == ir.ValReg { regs = append(regs, v.Name) }
   121→	}
   122→	switch inst.Kind {
   123→	case ir.InstBinop, ir.InstICmp, ir.InstFCmp:
   124→		add(inst.LHS); add(inst.RHS)
   125→	case ir.InstNeg, ir.InstCast:
   126→		add(inst.Operand)
   127→	case ir.InstLoad:
   128→		add(inst.Ptr)
   129→	case ir.InstStore:
   130→		add(inst.Val); add(inst.Ptr)
   131→	case ir.InstGEP:
   132→		add(inst.Ptr); add(inst.Idx)
