// fir Optimizer — P3.2 Dead Code Elimination
// 결과가 사용되지 않는 instruction 제거
//
// 알고리즘:
//   1. alive 집합: ret/br/store/call = 항상 alive
//   2. alive instruction의 모든 operand reg → alive에 추가
//   3. 역방향 전파 (수렴까지 반복)
//   4. alive 아닌 instruction 제거
package opt

import "fir/src/ir"

// ----------------------------------------------------------------
// DCEPass
// ----------------------------------------------------------------

type DCEPass struct{}

func (p *DCEPass) Name() string { return "dce" }

func (p *DCEPass) Run(mod *ir.Module) *ir.Module {
	for _, fn := range mod.Functions {
		dceFunc(fn)
	}
	return mod
}

// ----------------------------------------------------------------
// 함수 단위 DCE
// ----------------------------------------------------------------

func dceFunc(fn *ir.Function) {
	// 전체 instruction 수집
	allInsts := []*ir.Inst{}
	for _, b := range fn.Blocks {
		allInsts = append(allInsts, b.Insts...)
	}

	// alive 집합: result 이름 → true
	alive := make(map[string]bool)

	// 1. 초기 alive: 사이드 이펙트 있는 instruction
	for _, inst := range allInsts {
		if isSideEffect(inst) {
			markAlive(alive, inst)
		}
	}

	// 2. use-def 체인으로 역방향 전파
	// result → inst 맵
	defMap := make(map[string]*ir.Inst)
	for _, inst := range allInsts {
		if inst.Result != "" {
			defMap[inst.Result] = inst
		}
	}

	// alive인 instruction의 operand를 alive로 마킹 (수렴까지)
	for {
		changed := false
		for _, inst := range allInsts {
			if !isInstAlive(alive, inst) { continue }
			for _, used := range usedRegs(inst) {
				if !alive[used] {
					alive[used] = true
					changed = true
					// used를 정의하는 instruction도 alive
					if def, ok := defMap[used]; ok {
						markAlive(alive, def)
					}
				}
			}
		}
		if !changed { break }
	}

	// 3. 제거
	for _, b := range fn.Blocks {
		kept := b.Insts[:0]
		for _, inst := range b.Insts {
			if isSideEffect(inst) || isInstAlive(alive, inst) {
				kept = append(kept, inst)
			}
		}
		b.Insts = kept
	}
}

// ----------------------------------------------------------------
// 헬퍼
// ----------------------------------------------------------------

// 사이드 이펙트: 항상 alive
func isSideEffect(inst *ir.Inst) bool {
	switch inst.Kind {
	case ir.InstRet, ir.InstRetVoid,
		ir.InstBr, ir.InstBrCond,
		ir.InstStore, ir.InstCall:
		return true
	}
	return false
}

// instruction이 alive 집합에 포함되는가
func isInstAlive(alive map[string]bool, inst *ir.Inst) bool {
	if inst.Result == "" { return isSideEffect(inst) }
	return alive[inst.Result]
}

func markAlive(alive map[string]bool, inst *ir.Inst) {
	if inst.Result != "" {
		alive[inst.Result] = true
	}
}

// instruction이 사용하는 레지스터 이름 목록
func usedRegs(inst *ir.Inst) []string {
	var regs []string
	add := func(v *ir.Value) {
		if v != nil && v.Kind == ir.ValReg { regs = append(regs, v.Name) }
	}
	switch inst.Kind {
	case ir.InstBinop, ir.InstICmp, ir.InstFCmp:
		add(inst.LHS); add(inst.RHS)
	case ir.InstNeg, ir.InstCast:
		add(inst.Operand)
	case ir.InstLoad:
		add(inst.Ptr)
	case ir.InstStore:
		add(inst.Val); add(inst.Ptr)
	case ir.InstGEP:
		add(inst.Ptr); add(inst.Idx)
	case ir.InstCall:
		add(inst.Callee)
		for _, a := range inst.Args { add(a) }
	case ir.InstBrCond:
		add(inst.Cond)
	case ir.InstRet:
		add(inst.Val)
	case ir.InstPhi:
		for _, inc := range inst.Incoming { add(inc.Val) }
	}
	return regs
}

