// ----------------------------------------------------------------

func makeBlockMap(fn *ir.Function) map[string]*ir.Block {
	m := make(map[string]*ir.Block, len(fn.Blocks))
	for _, b := range fn.Blocks {
		m[b.Label] = b
	}
	return m
}

func buildPreds(fn *ir.Function) map[string][]string {
	preds := make(map[string][]string, len(fn.Blocks))
	for _, b := range fn.Blocks {
		preds[b.Label] = nil
	}
	for _, b := range fn.Blocks {
		for _, succ := range successors(b) {
			preds[succ] = append(preds[succ], b.Label)
		}
	}
	return preds
}

// ----------------------------------------------------------------
// 3. Dominance (Cooper et al. iterative)
// ----------------------------------------------------------------

func computeIDom(fn *ir.Function, preds map[string][]string) map[string]string {
	rpo := reversePostOrder(fn)
	rpoIdx := make(map[string]int, len(rpo))
	for i, label := range rpo {
		rpoIdx[label] = i
	}

	entry := fn.Blocks[0].Label
	idom := make(map[string]string, len(fn.Blocks))
	idom[entry] = entry

	for changed := true; changed; {
		changed = false
		for _, label := range rpo {
			if label == entry {
				continue
			}
			newIdom := ""
			for _, p := range preds[label] {
				if idom[p] == "" {
					continue
				}
				if newIdom == "" {
					newIdom = p
				} else {
					newIdom = domIntersect(newIdom, p, idom, rpoIdx)
				}
			}
			if newIdom == "" {
				newIdom = entry
			}
			if idom[label] != newIdom {
				idom[label] = newIdom
				changed = true
			}
		}
	}
	return idom
}

func domIntersect(a, b string, idom map[string]string, rpoIdx map[string]int) string {
	for a != b {
		for rpoIdx[a] > rpoIdx[b] {
			a = idom[a]
		}
		for rpoIdx[b] > rpoIdx[a] {
			b = idom[b]
		}
	}
	return a
}

func reversePostOrder(fn *ir.Function) []string {
	blockMap := makeBlockMap(fn)
	visited := make(map[string]bool, len(fn.Blocks))
	post := make([]string, 0, len(fn.Blocks))

	var dfs func(label string)
	dfs = func(label string) {
		if visited[label] {
			return
		}
		visited[label] = true
		if b, ok := blockMap[label]; ok {
			for _, succ := range successors(b) {
				dfs(succ)
			}
		}
		post = append(post, label)
	}
	dfs(fn.Blocks[0].Label)

