func astTypeToIR(t *AstType) *ir.Type {
	if t == nil { return ir.Void() }
	switch t.Name {
	case "i8":   return ir.I8()
	case "i16":  return ir.I16()
	case "i32":  return ir.I32()
	case "i64":  return ir.I64()
	case "u8":   return ir.U8()
	case "u16":  return ir.U16()
	case "u32":  return ir.U32()
	case "u64":  return ir.U64()
	case "f32":  return ir.F32()
	case "f64":  return ir.F64()
	case "bool": return ir.Bool()
	case "void": return ir.Void()
	case "ptr":
		if t.Inner != nil { return ir.Ptr(astTypeToIR(t.Inner)) }
		return ir.Ptr(ir.Void())
	}
	return ir.I64() // 기본: i64
