// Free IR 1.0 — Reference Interpreter
// 정확성 100% 목표. 속도 무관.
package interp

import (
	"fmt"
	"fir/src/ir"
	"math"
)

// ----------------------------------------------------------------
// Value (런타임 값)
// ----------------------------------------------------------------

type RVal struct {
	I int64
	F float64
	IsFloat bool
}

func rInt(v int64) RVal     { return RVal{I: v} }
func rFloat(v float64) RVal { return RVal{F: v, IsFloat: true} }

// 외부 공개
func RInt(v int64) RVal     { return rInt(v) }
func RFloat(v float64) RVal { return rFloat(v) }

func (r RVal) AsInt() int64 {
	if r.IsFloat { return int64(r.F) }
	return r.I
}
func (r RVal) AsFloat() float64 {
	if r.IsFloat { return r.F }
	return float64(r.I)
}
func (r RVal) Bool() bool { return r.I != 0 }

// ----------------------------------------------------------------
// Env (실행 환경)
// ----------------------------------------------------------------

type Env struct {
	Regs    map[string]RVal
	Memory  []RVal
	MemPtr  int
	Globals map[string]RVal
	FuncMap map[string]*ir.Function
}

func newEnv(globals map[string]RVal, funcMap map[string]*ir.Function) *Env {
	return &Env{
		Regs:    make(map[string]RVal),
		Memory:  make([]RVal, 0, 256),
		MemPtr:  0,
		Globals: globals,
		FuncMap: funcMap,
	}
}

func (e *Env) getReg(name string) RVal {
